// RELATED: src/Nethermind/Nethermind.Merge.Plugin/Handlers/GetBlobsHandlerV2.cs:GetBlobsHandlerV2.HandleAsync (lines 20-65)
// EL-side: engine_getBlobsV2 returns blob+cellProofs from txPool for CL distributed blob publishing
// NOTE: Data availability checks and fork choice for data columns are CL-side concerns (beacon node).
public Task<ResultWrapper<IEnumerable<BlobAndProofV2>?>> HandleAsync(byte[][] request)
{
    var count = txPool.GetBlobCounts(request);
    if (count != request.Length) return ReturnEmptyArray(); // returns null if any blob missing
    foreach (byte[] requestedBlobVersionedHash in request)
    {
        if (txPool.TryGetBlobAndProofV1(requestedBlobVersionedHash, out byte[]? blob, out byte[][]? cellProofs))
            response.Add(new BlobAndProofV2(blob, cellProofs));
        else { response.Dispose(); return ReturnEmptyArray(); }
    }
}

