// PRIMARY: src/Nethermind/Nethermind.Core/BaseFeeCalculator.cs:DefaultBaseFeeCalculator.Calculate (lines 19-65)
// EIP-1559 base fee independently computed from parent:
public UInt256 Calculate(BlockHeader parent, IEip1559Spec specFor1559)
{
    UInt256 expectedBaseFee = parent.BaseFeePerGas;
    if (specFor1559.IsEip1559Enabled)
    {
        long parentGasTarget = parent.GasLimit / specFor1559.ElasticityMultiplier;
        if (parent.GasUsed > parentGasTarget)
        {
            gasDelta = parent.GasUsed - parentGasTarget;
            feeDelta = UInt256.Max(parentBaseFee * (UInt256)gasDelta / (UInt256)parentGasTarget / specFor1559.BaseFeeMaxChangeDenominator, UInt256.One);
            expectedBaseFee = parentBaseFee + feeDelta;
        } // ... else decrease
    }
    return expectedBaseFee;
}
// Validate1559 in HeaderValidator: if (expectedBaseFee != header.BaseFeePerGas) return false;

