// PRIMARY: src/Nethermind/Nethermind.Consensus/Withdrawals/WithdrawalProcessor.cs:ProcessWithdrawals (lines 25-47)
public void ProcessWithdrawals(Block block, IReleaseSpec spec)
{
    if (!spec.WithdrawalsEnabled) return;
    if (block.Withdrawals is not null)
    {
        Withdrawal[] blockWithdrawals = block.Withdrawals;
        for (int i = 0; i < blockWithdrawals.Length; i++)
        {
            Withdrawal withdrawal = blockWithdrawals[i];
            if (_logger.IsTrace) _logger.Trace($"  {withdrawal.AmountInGwei} GWei to account {withdrawal.Address}");
            // Consensus clients are using Gwei for withdrawals amount.
            _stateProvider.AddToBalanceAndCreateIfNotExists(withdrawal.Address, withdrawal.AmountInWei, spec);
        }
    }
}
// ETH credited directly to withdrawal.Address - no substitution or redirection.

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:Bloom (lines 18-269)
public class Bloom : IEquatable<Bloom>
{
    public const int BitLength = 2048;
    public const int ByteLength = BitLength / 8; // = 256
    private BloomData _bloomData; // [InlineArray(ByteLength)] - exactly 256 bytes on stack
    public Span<byte> Bytes => _bloomData.AsSpan(); // Always 256 bytes
}
// BloomData uses [InlineArray(ByteLength)] = 256 bytes, fixed size struct
// No dynamic allocation - always exactly 256 bytes
// WordMask ensures index within [0, 31] for ulong array (256/8 = 32 ulongs)

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:BloomExtract (lines 240-247)
public readonly struct BloomExtract(ulong indexes)
{
    public int Index1 => 2047 - (int)((indexes >> 48) & 0x07FF); // 0x07FF mask applied
    public int Index2 => 2047 - (int)((indexes >> 32) & 0x07FF); // Index always in [0,2047]
    public int Index3 => 2047 - (int)((indexes >> 16) & 0x07FF); // = 2047 - [0..2047]
}
// 0x07FF = 11-bit mask. indexes extracted from first 8 bytes of Keccak hash.
// (indexes >> 48) & 0x07FF extracts bits [48..58] = 11 bits → [0..2047]
// 2047 - [0..2047] → also [0..2047]. All indices correctly bounded.

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:WordMask (lines 202-213)
[MethodImpl(MethodImplOptions.AggressiveInlining)]
private static (int wordIndex, ulong mask) WordMask(int bitIndex)
{
    const int LittleEndianReverseMask = 7;
    const int BigEndianReverseMask = 63;
    int wordIndex = bitIndex >> 6;  // bitIndex / 64 → wordIndex in [0..31]
    bitIndex &= 63;                  // bitIndex % 64
    int mirrorMask = BitConverter.IsLittleEndian ? LittleEndianReverseMask : BigEndianReverseMask;
    int shift = bitIndex ^ mirrorMask;
    ulong mask = 1UL << shift;
    return (wordIndex, mask);
}
// Index from BloomExtract is [0..2047]. wordIndex = [0..2047]>>6 = [0..31] (within 32 ulongs = 256 bytes)

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:Bloom.Set (lines 59-78)
public void Set(ReadOnlySpan<byte> sequence, Bloom? masterBloom = null)
{
    BloomExtract indexes = GetExtract(sequence); // Extracts exactly 3 indices from Keccak
    (int w1, ulong m1) = WordMask(indexes.Index1);
    (int w2, ulong m2) = WordMask(indexes.Index2);
    (int w3, ulong m3) = WordMask(indexes.Index3);
    SetWordMasks(w1, m1, w2, m2, w3, m3); // Sets exactly 3 bits (may collide)
    masterBloom?.SetWordMasks(w1, m1, w2, m2, w3, m3);
}
// BloomExtract: Index1=(hash>>48)&0x07FF, Index2=(hash>>32)&0x07FF, Index3=(hash>>16)&0x07FF
// Exactly 3 indices extracted from first 6 bytes of keccak - inline struct, no loop

