public class Bloom : IEquatable<Bloom>
{
    public static readonly Bloom Empty = new(); // Pre-allocated empty bloom
    private BloomData _bloomData; // [InlineArray(ByteLength)] - zero-initialized by C# runtime
    public Bloom() { } // Default: BloomData is value-type, zero-initialized by CLR
    public Bloom(LogEntry[]? logEntries) { if (logEntries is null) return; Add(logEntries); }
}
// C# InlineArray structs are zero-initialized by CLR on construction
// No buffer reuse pattern - new Bloom() always starts from zero
// Bloom.Empty is a pre-allocated constant - ThrowInvalidUpdate() prevents mutation

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:Bloom.Add (lines 117-131)
public void Add(LogEntry[] logEntries)
{
    for (int entryIndex = 0; entryIndex < logEntries.Length; entryIndex++)
    {
        LogEntry logEntry = logEntries[entryIndex];
        byte[] addressBytes = logEntry.Address.Bytes;
        Set(addressBytes); // Each log address added exactly once per log entry
        Hash256[] topics = logEntry.Topics;
        for (int topicIndex = 0; topicIndex < topics.Length; topicIndex++)
        {
            Hash256 topic = topics[topicIndex];
            Set(topic.Bytes); // Each topic added exactly once
        }
    }
}
// Simple sequential loop - each log address processed exactly once, no skipping.

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:Bloom.Add (lines 117-131)
// For each log entry: 1 Set(address) + N Set(topics) where N = logEntry.Topics.Length
// Inner loop: for (int topicIndex = 0; topicIndex < topics.Length; topicIndex++)
//     Set(topic.Bytes) — each topic added exactly once, in order
// Total Set calls per log = 1 (address) + len(topics)
// For logs with 0 topics: inner loop does not execute → only address added
// For logs with 4 topics: inner loop executes 4 times → 4 topics + 1 address = 5 Set calls
